const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // Define the approximate location of the Monte Pisano fire event.
    const fireLocation = ee.Geometry.Point([10.51, 43.75]);

    // Define the date of interest. Landsat overpass is around 10:00 UTC, which matches the local time specified.
    const startDate = '2019-02-25';
    const endDate = '2019-02-26';

    // 2. Data Acquisition
    // Use Landsat 8 Collection 2, Tier 1, Surface Reflectance.
    let imageCollection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterBounds(fireLocation)
        .filterDate(startDate, endDate);

    const imageCount = imageCollection.size().getInfo();
    if (imageCount === 0) {
        console.log("Evidence: No Landsat 8 images found for the specified date and location.");
        console.log("A"); // C1 is not the answer as the question states an image exists. We will provide a definitive no if we can't find it.
        return;
    }

    const image = ee.Image(imageCollection.first());

    // 3. Cloud Masking (though for smoke analysis, it's tricky)
    // We will use a simple cloud mask to ensure we are not confusing clouds with smoke.
    function maskL8sr(image) {
        const cloudShadowBitMask = (1 << 4);
        const cloudsBitMask = (1 << 3);
        const qa = image.select('QA_PIXEL');
        const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
            .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
        return image.updateMask(mask);
    }

    const maskedImage = maskL8sr(image);

    // 4. Analysis Logic
    // Define two points: one at the fire's origin, and one slightly to the east.
    // If smoke is moving east, the eastern point should have a higher aerosol signature (or a brighter value in visible bands)
    // than a point to the west, controlling for distance from the fire.

    const pointWest = ee.Geometry.Point([10.46, 43.75]); // West of the fire
    const pointEast = ee.Geometry.Point([10.56, 43.75]); // East of the fire

    // The 'SR_AEROSOL' band indicates aerosol quantity. Smoke consists of aerosols.
    // We will compare the aerosol values at these two points.
    // A higher value in the east suggests an eastward plume.
    // We use a larger scale (300m) to average the area and reduce noise from specific pixels.
    const aerosolWest = maskedImage.select('SR_AEROSOL').reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: pointWest.buffer(150),
        scale: 30,
        maxPixels: 1e9
    }).get('SR_AEROSOL');

    const aerosolEast = maskedImage.select('SR_AEROSOL').reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: pointEast.buffer(150),
        scale: 30,
        maxPixels: 1e9
    }).get('SR_AEROSOL');

    // Retrieve the values
    const valWest = aerosolWest.getInfo();
    const valEast = aerosolEast.getInfo();

    // 5. Validation & Final Answer
    if (valWest === null || valEast === null) {
        console.log("Evidence: Could not calculate aerosol values for comparison points.");
        console.log("C3");
        return;
    }

    console.log(`Evidence: Aerosol value west of fire: ${valWest.toFixed(2)}`);
    console.log(`Evidence: Aerosol value east of fire: ${valEast.toFixed(2)}`);

    if (valEast > valWest) {
        console.log("Conclusion: Aerosol concentration is higher east of the fire, indicating an eastward plume.");
        console.log("A");
    } else {
        console.log("Conclusion: Aerosol concentration is not higher east of the fire.");
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e.message}`);
    console.log("D");
});
